39	const DoorCameraController: FC<DoorCameraControllerProps> = ({
40	  controlsRef,
41	  doorFocusY,
42	  isFront,
43	}) => {
44	  const { camera, invalidate } = useThree();
45	
46	  useEffect(() => {
47	    const controls = controlsRef.current;
48	
49	    if (!controls) return;
