import { DESIGN_COLLECTIONS } from '@modules/door-model/const';
import {
  useDoorCollection,
  useDoorDesign,
  useSetDoorDesign,
} from '@modules/door-model/store';
import { isCollectionGuard } from '@modules/door-model/util';
import { FC, useMemo } from 'react';
import { OptionListItem } from '../OptionListItem';
import { OptionListTitle } from '../OptionListTitle';

export const Design: FC = () => {
  const collection = useDoorCollection();
  const design = useDoorDesign();
  const currentDesigns = useMemo(() => {
    if (!collection.name || !isCollectionGuard(collection.name)) {
      return DESIGN_COLLECTIONS['Horizont'];
    }
    return DESIGN_COLLECTIONS[collection.name];
  }, [collection.name]);

  const setDesign = useSetDoorDesign();

  return (
    <>
      <OptionListTitle title="Design" value={design.name} />
      <div className="flex mb-40 flex-wrap">
        {currentDesigns.map((item) => (
          <OptionListItem
            key={item.id}
            item={item}
            activeItem={design}
            imageWidth={32}
            imageHeight={56}
            setDirection={setDesign}
          />
        ))}
      </div>
    </>
  );
};
